import Cookies from 'js-cookie';
import { getElement } from '../utils/functional';
import { Module } from './module/module'; // eslint-disable-next-line import/no-default-export

export default class _class extends Module {
  initialize() {
    this.setupObserver();
    if (Cookies.get(this.cookieName) === 'true' || !Cookies.get(this.siteCookieName)) return;
    this.element.setAttribute(this.activeAttribute, 'false');
  }

  setupListeners() {
    this.closeButtonEls.forEach(closeButton => {
      const closeBanner = () => {
        Cookies.set(this.cookieName, 'true', {
          expires: 3650
        });
        this.element.setAttribute(this.activeAttribute, 'true');
      };

      this.listeners.add(closeButton, 'click', closeBanner);
    });
  }

  setupObserver() {
    const observer = new MutationObserver(() => {
      if (this.storeSwitcher.getAttribute('aria-expanded') === 'false') {
        this.element.setAttribute(this.activeAttribute, 'false');
        observer.disconnect();
      }
    });
    observer.observe(this.storeSwitcher, {
      attributes: true
    });
  }

  get activeAttribute() {
    return 'aria-hidden';
  }

  get cookieName() {
    return 'BAO-cookie-newsletter';
  }

  get siteCookieName() {
    return "BAO-store-".concat(this.currentStoreId);
  }

  get storeSwitcher() {
    return getElement('.mod-Modal-storeSwitcher');
  }

  get currentStoreId() {
    return this.data.get('currentStoreId');
  }

}
_class.targets = ['closeButton', 'data'];